package com.aaliyun.leadnews.ai;
import com.aaliyun.leadnews.ai.client.AiModelClient;import com.aaliyun.leadnews.ai.config.*;import com.aaliyun.leadnews.ai.model.AiCallResult;import com.aaliyun.leadnews.ai.service.AiWritingService;import com.aaliyun.leadnews.ai.support.PromptCatalog;import com.aaliyun.leadnews.common.exception.BusinessException;import com.aaliyun.leadnews.model.ai.*;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import org.junit.jupiter.api.Test;import reactor.core.publisher.Flux;import java.time.Duration;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class AiWritingServiceTest{private AiWritingService service(AiModelClient model){PromptCatalog prompts=mock(PromptCatalog.class);when(prompts.load(anyString())).thenReturn("{title}|{labels}|{content}|{minLength}|{maxLength}|{instruction}|{targetLength}");var p=new AiBusinessProperties(new AiBusinessProperties.Summary(10,30,1000),new AiBusinessProperties.Continuation(100,1000,1000,100));return new AiWritingService(model,prompts,TestFixtures.properties(Duration.ofSeconds(1),1,2),p,new SimpleMeterRegistry());}
 @Test void summaryCleansAndValidatesOutput(){AiModelClient m=mock(AiModelClient.class);when(m.chat(anyString(),anyString())).thenReturn(new AiCallResult("摘要：这是一个长度合规的可靠文章摘要", "r",12,null));var r=service(m).summarize(new ArticleSummaryRequest(1L,1,"t","l","正文正文"));assertThat(r.summary()).isEqualTo("这是一个长度合规的可靠文章摘要");}
 @Test void emptySummaryFailsClosed(){AiModelClient m=mock(AiModelClient.class);when(m.chat(anyString(),anyString())).thenReturn(new AiCallResult("",null,1,null));assertThatThrownBy(()->service(m).summarize(new ArticleSummaryRequest(1L,1,"t",null,"正文"))).isInstanceOf(BusinessException.class);}
 @Test void shortArticleUsesGroundedAdaptiveMinimum(){assertThat(AiWritingService.effectiveSummaryMin("短文章只有有限事实",80)).isEqualTo(10);assertThat(AiWritingService.effectiveSummaryMin("长".repeat(300),80)).isEqualTo(80);}
 @Test void continuationUsesRealUpstreamChunks(){AiModelClient m=mock(AiModelClient.class);when(m.stream(anyString(),anyString())).thenReturn(Flux.just("第一段","第二段","第三段"));assertThat(service(m).continueArticle(new ArticleContinuationRequest("t","已有正文","继续",200)).collectList().block()).containsExactly("第一段","第二段","第三段");}
}
